#!/usr/bin/env bash
# Sourced by the platform packagers. Stages the distributable payload without any Mojang-derived
# carrier: those are built per user on first run from the bundled prep kit.
set -euo pipefail

repo_root="$(CDPATH= cd -- "${CINNABAR_SOURCE_ROOT:-$(dirname -- "${BASH_SOURCE[0]}")/../..}" && pwd)"

# Every checkout-relative file `assetc prepare --kit` reads, one per line, generated by
# `assetc kit-files`; an asset-compiler test fails when it goes stale.
prep_kit_list="$repo_root/packaging/common/prep-kit-files.txt"
prep_kit_hint='regenerate it with cargo run -p asset-compiler --bin assetc -- kit-files'

runtime_binary_list="$repo_root/packaging/common/runtime-binaries.txt"

# runtime_binaries: executable basenames shared by builders, signing and payload checks.
runtime_binaries() {
    awk '{print $1}' "$runtime_binary_list"
}

# The DX12 shader compiler pin travels with these scripts, like the fetch-dxc.ps1 that installs it,
# so a payload and its check agree when an older source checkout is packaged.
dxc_pin="$(CDPATH= cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)/windows/dxc.json"

# windows_runtime_libraries: DLLs Windows payloads install beside the runtime executables.
windows_runtime_libraries() {
    sed -n 's/^[[:space:]]*"library"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' "$dxc_pin"
}

# runtime_binary_source <name> <override>: a configured executable or its sibling build output.
runtime_binary_source() {
    local name="$1" override="$2" directory
    directory="${BINARIES:-$(dirname -- "${LOCAL_SERVER:-${CORE:-${CLIENT:-$repo_root/target/release/_}}}")}"
    printf '%s\n' "${!override:-$directory/$name}"
}

# stage_runtime_binaries <destination>: require and install every runtime executable together.
stage_runtime_binaries() {
    local destination="$1" name package override source
    require_file "$runtime_binary_list" 'restore the runtime binary table'
    mkdir -p "$destination"
    while read -r name package override; do
        source="$(runtime_binary_source "$name" "$override")"
        require_file "$source" 'build with make package-binaries'
        install -m 0755 "$source" "$destination/$name"
    done < <(tr -d '\r' < "$runtime_binary_list")
}

# prep_kit_files: the listed paths. Callers check the list exists first: this often runs in a subshell.
prep_kit_files() {
    tr -d '\r' < "$prep_kit_list"
}

# stage_prep_kit <kit_dir> <assetc_binary>: the compiler plus each listed file at its checkout path.
stage_prep_kit() {
    local kit="$1" assetc="$2" file
    require_file "$prep_kit_list" "$prep_kit_hint"
    rm -rf "$kit"
    mkdir -p "$kit/bin"
    install -m 0755 "$assetc" "$kit/bin/$(basename "$assetc")"
    while IFS= read -r file; do
        mkdir -p "$kit/$(dirname -- "$file")"
        install -m 0644 "$repo_root/$file" "$kit/$file"
    done < <(prep_kit_files)
}

# stage_resources <resource_root> <assetc_binary>: physics registry, notices, licenses, UI font, prep kit.
stage_resources() {
    local resources="$1" assetc="$2"
    mkdir -p "$resources/assets"
    install -m 0644 "$repo_root/crates/assets/data/block-physics-v2193.bin" "$resources/assets/block-physics-v2193.bin"
    install -m 0644 "$repo_root/THIRD_PARTY_NOTICES.md" "$resources/assets/THIRD_PARTY_NOTICES.md"
    mkdir -p "$resources/licenses"
    install -m 0644 "$repo_root/LICENSE" "$resources/licenses/Cinnabar-LICENSE.md"
    cp "$repo_root"/assets/licenses/* "$resources/licenses/"
    local font
    font="$(ui_font_path)"
    require_file "$font" 'restore the bundled Cinnangles Sans source'
    install -d "$resources/fonts"
    install -m 0644 "$font" "$resources/fonts/${font##*/}"
    stage_prep_kit "$resources/prep-kit" "$assetc"
}

# ui_font_path: the bundled Cinnangles Sans source; first-run draws with it.
ui_font_path() {
    local manifest="$repo_root/assets/cinnangles-sans-source.json" file
    file="$(sed -n 's/^[[:space:]]*"font_file"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' "$manifest" | head -n 1)"
    printf '%s\n' "$repo_root/assets/fonts/$file"
}

# resource_manifest <macos|linux|windows>: every file stage_resources (or build-installer.ps1)
# writes under the resource root, one relative path per line. Optional endpoint files excluded.
resource_manifest() {
    local platform="$1" exe='' file
    [[ "$platform" != windows ]] || exe=.exe
    file="$(ui_font_path)"
    printf '%s\n' licenses/Cinnabar-LICENSE.md assets/block-physics-v2193.bin assets/THIRD_PARTY_NOTICES.md "fonts/${file##*/}" "prep-kit/bin/assetc$exe"
    for file in "$repo_root"/assets/licenses/*; do printf 'licenses/%s\n' "${file##*/}"; done
    prep_kit_files | sed 's|^|prep-kit/|'
}

# require_file <path> <hint>
require_file() {
    [[ -f "$1" ]] || { printf 'missing %s (%s)\n' "$1" "$2" >&2; exit 1; }
}

# version_of: workspace package version, the single release version source.
version_of() {
    sed -n '/^\[workspace.package\]/,/^\[/{s/^version = "\(.*\)"/\1/p;}' "$repo_root/Cargo.toml" | head -n 1
}
